#!/bin/bash
# Regenerates Sources/ExactJPEG/ShaderSource.swift from the .metal files (the library compiles them at run time,
# so no resource bundle is needed by the C library or by iOS apps). Run after editing any .metal file;
# scripts/test.sh checks that the generated file is up to date.
set -euo pipefail
cd "$(dirname "$0")/.."
out=Sources/ExactJPEG/ShaderSource.swift
{
  echo "// GENERATED by scripts/gen-shaders.sh from Sources/ExactJPEG/Shaders/*.metal. Do not edit."
  echo "enum ShaderSource {"
  for f in Common Decode Encode; do
    echo "    static let $(echo $f | tr 'A-Z' 'a-z') = #\"\"\""
    cat "Sources/ExactJPEG/Shaders/$f.metal"
    echo "\"\"\"#"
  done
  echo "}"
} > "$out.tmp"
mv "$out.tmp" "$out"
